INSERT INTO `makes` VALUES (1,'http://sipi.sic.gov.co/sipi/View.ashx?540476',0,NULL,'[{\"code\": 44, \"more\": \"La clase 44 comprende principalmente los tratamientos médicos, incluida la medicina alternativa, y tratamientos de higiene y de belleza destinados a personas o animales, prestados por personas o establecimientos, así como los servicios en relación con los sectores de la agricultura, la acuicultura, la horticultura y la silvicultura.\\nEsta clase comprende en particular:\\n\\n    •  los servicios hospitalarios\\n    •  los servicios de telemedicina\\n    •  los servicios de odontología, optometría y salud mental\\n    •\", \"note\": \"Servicios médicos; servicios veterinarios; tratamientos de higiene y de belleza para personas o animales; servicios de agricultura, acuicultura, horticultura y silvicultura\\n\"}]','[{\"code\": \"44\", \"text\": \"SERVICIOS MÉDICOS, SERVICIOS DE EVALUACIÓN MÉDICA, SERVICIOS CLÍNICOS, PROVEER SERVICIOS DE CIRUGÍA PLÁSTICA, ESTÉTICA Y RECONSTRUCTIVA, PROCEDIMIENTOS QUIRÚRGICOS, SERVICIOS DE APOYO O RELACIONADOS.\"}]',0,0,0,'1852946012100421','9976DE','7a9c1a18d25cf0cbfbcb1463be73b053',105,'372afc832166f5102e79a65f83df5667',NULL,3,NULL,NULL,NULL,'SURGICAL GROUP','2025-12-30 15:03:41',NULL,'SURGICAL GROUP',NULL,'[10]','DANIEL  RESTREPO SOTO','SURGICAL GROUP S.A.S.',NULL,'12126638',NULL,'2032-11-28',NULL,'',0,NULL,'2012-11-28','2012-08-15','',NULL,'2012-07-27'),(2,'http://sipi.sic.gov.co/sipi/View.ashx?577674',0,NULL,'[{\"code\": 36, \"more\": \"La clase 36 comprende principalmente los servicios relativos a los servicios bancarios y otras transacciones financieras, los servicios de valoración, así como las actividades de seguros y de bienes inmuebles.\\nEsta clase comprende en particular:\\n\\n    •  los servicios de pago y de transacciones financieras, por ejemplo: las operaciones de cambio, la transferencia electrónica de fondos, el procesamiento de pagos por tarjeta de crédito y de débito, la emisión de cheques de viaje\\n    •  la gestión y la investig\", \"note\": \"Servicios financieros, monetarios y bancarios; servicios de seguros; servicios inmobiliarios\"}, {\"code\": 43, \"more\": \"La clase 43 comprende principalmente los servicios prestados en relación con la preparación de alimentos y bebidas para el consumo, así como los servicios de puesta a disposición de alojamiento temporal.\\nEsta clase comprende en particular:\\n\\n    •  la reserva de alojamiento temporal, por ejemplo, la reserva de hoteles\\n    •  los servicios de residencias para animales\\n    •  el alquiler de salas de reunión, tiendas de campaña y construcciones transportables\\n    •  los servicios de residencias para la tercera \", \"note\": \"Servicios de restauración (alimentación); hospedaje temporal\"}]','[{\"code\": \"36\", \"text\": \"NEGOCIOS INMOBILIARIOS, PARTICIPACIÓN EN PROYECTOS DE CONSTRUCCIÓN DE CONJUNTOS RESIDENCIALES, VIVIENDAS, APARTAMENTOS, PARQUES, ZONAS COMUNES.\"}, {\"code\": \"43\", \"text\": \"SERVICIOS HOTELEROS, HOSPEDAJE TEMPORAL, SERVICIOS DE ADMINISTRACIÓN HOTELERA, TIEMPOS COMPARTIDOS, SERVICIOS DE RESORT.\"}]',0,0,0,'1852946012119637','548BF2','4e9c5362b585740a1984b122af58890d',105,'43cf3ac0bbe962a8c783e4c40981101e',NULL,10,NULL,NULL,NULL,'family - PROYECTOS INMOBILIARIOS','2025-12-30 15:03:41',NULL,'family - PROYECTOS INMOBILIARIOS',NULL,'[10]','DANIEL  RESTREPO SOTO','FASEPREVIA S.A.S.',NULL,'14268658',NULL,'2025-03-31',NULL,'',0,NULL,'2015-03-31','2015-01-15','',NULL,'2014-12-05'),(3,'http://sipi.sic.gov.co/sipi/View.ashx?579246',0,NULL,'[{\"code\": 31, \"more\": \"La clase 31 comprende principalmente los productos de la tierra y del mar que no hayan sido procesados para su consumo, los animales vivos y las plantas vivas, así como los alimentos para animales.\\nEsta clase comprende en particular:\\n\\n    •  los cereales sin procesar\\n    •  las frutas, verduras, hortalizas y legumbres frescas, incluso lavadas o enceradas\\n    •  los residuos de origen vegetal\\n    •  las algas sin procesar\\n    •  la madera sin desbastar\\n    •  los huevos fertilizados para incubar\\n    •  las t\", \"note\": \"Productos agrícolas, acuícolas, hortícolas y forestales en bruto y sin procesar; granos y semillas en bruto o sin procesar; frutas y verduras, hortalizas y legumbres frescas, hierbas aromáticas frescas; plantas y flores naturales; bulbos, plantones y semillas para plantar; animales vivos; productos alimenticios y bebidas para animales; malta\\n\"}]','[{\"code\": \"31\", \"text\": \"PRODUCTOS AGRÍCOLAS, HORTÍCOLAS, FORESTALES, ANIMALES VIVOS, SEMILLAS, PLANTAS, ALIMENTOS PARA ANIMALES.\"}]',0,0,0,'1852946012140072','B68148','281f3cbc0e7a610e90873cf49189292f',105,'92146f00df8c9109ebfb02dcb2144945',NULL,3,NULL,NULL,NULL,'MaxiPELLET´S','2025-12-30 15:03:41',NULL,'MaxiPELLET´S',NULL,'[10]','DANIEL  RESTREPO SOTO','AGROPECUARIA VILLA LINA S.A.S.',NULL,'13053482',NULL,'2034-06-25',NULL,'',0,NULL,'2014-06-25','2013-03-22','',NULL,'2013-03-18'),(4,'http://sipi.sic.gov.co/sipi/View.ashx?589363',0,NULL,'[{\"code\": 35, \"more\": \"Creación de marcas; servicios de marketing; servicios de desarrollo creativo para campañas de marketing; servicios de agencia de publicidad; servicios de mercadeo digital.\", \"note\": \"Publicidad; gestión, organización y administración de negocios comerciales; trabajos de oficina.\"}]','[{\"code\": \"35\", \"text\": \"PUBLICIDAD; GESTIÓN DE NEGOCIOS COMERCIALES; ADMINISTRACIÓN COMERCIAL; TRABAJOS DE OFICINA.\"}]',0,0,0,'1852946012158708','9976DE','ac2b2bc206b5e80169b17eb0fe19ecb5',105,'ec5a7846158a532edcf69f4623f751b2',NULL,3,NULL,NULL,NULL,'LaNubeDigital','2025-12-30 15:03:41',NULL,'LaNubeDigital',NULL,'[10]','DANIEL  RESTREPO SOTO','LANUBEDIGITAL S.A.S',NULL,'15047479',NULL,'2025-12-21',NULL,'',0,NULL,'2015-12-21','2015-03-20','',NULL,'2015-03-03'),(5,'http://sipi.sic.gov.co/sipi/View.ashx?589711',0,NULL,'[{\"code\": 35, \"more\": \"Creación de marcas; servicios de marketing; servicios de desarrollo creativo para campañas de marketing; servicios de agencia de publicidad; servicios de mercadeo digital.\", \"note\": \"Publicidad; gestión, organización y administración de negocios comerciales; trabajos de oficina.\"}, {\"code\": 42, \"more\": \"Servicios de diseño; diseño de marca; diseño de contenido; diseño gráfico; diseño visual; diseño de branding, diseño publicitario; desarrollo de software; servicios de diseño y desarrollo web.\", \"note\": \"Servicios científicos y tecnológicos, así como servicios de investigación y diseño conexos; servicios de análisis industrial, investigación industrial y diseño industrial; control de calidad y servicios de autenticación; diseño y desarrollo de hardware y software.\"}]','[{\"code\": \"35\", \"text\": \"CONSULTORÍA EN RECURSOS HUMANOS, GESTIÓN DE RECURSOS HUMANOS, ORIENTACIÓN PSICOLÓGICA PARA RECURSOS HUMANOS, CONSULTORÍA Y PRESTACIÓN DE SERVICIOS ESPECIALIZADOS Y PROFESIONALES EN TEMAS DE VALORACIÓN, DESARROLLO HUMANO, SELECCIÓN DE PERSONAL, IMPLEMENTACIÓN DE PRUEBAS SICOLÓGICAS, TEST PSICOTÉCNICOS PARA LA SELECCIÓN DE PERSONAL, EMPLEO DE PERSONAL, GESTIÓN DE PERSONAL Y DEMÁS AREAS RELACIONADAS.\"}, {\"code\": \"42\", \"text\": \"CONSULTARÍA Y PRESTACIÓN DE SERVICIOS ESPECIALIZADOS Y PROFESIONALES EN TEMAS DE VALORACIÓN, DESARROLLO HUMANO, SELECCIÓN DE PERSONAL, IMPLEMENTACIÓN DE PRUEBAS SICOLÓGICAS, Y DEMÁS ÁREAS RELACIONADAS. CONSULTORÍA ESPECIALIZADA EN BÚSQUEDA, DESARROLLO Y MANEJO DE PERSONAL Y RECURSO HUMANO.\"}]',0,0,0,'1852946012176375','B68148','49e993d0e2f9b614b8cf7868ded55c24',105,'33cddb074f6a20a093cd13b37ae14d24',NULL,3,NULL,NULL,NULL,'intus -ASESORES EN ESTRATEGIA PERSONAL-','2025-12-30 15:03:41',NULL,'intus -ASESORES EN ESTRATEGIA PERSONAL-',NULL,'[10]','DANIEL  RESTREPO SOTO','AURA MARIA PELAEZ ZULUAGA',NULL,'15049767',NULL,'2026-01-29',NULL,'',0,NULL,'2016-01-29','2015-04-30','',NULL,'2015-03-04'),(6,'http://sipi.sic.gov.co/sipi/View.ashx?613569',0,NULL,'[{\"code\": 35, \"more\": \"Creación de marcas; servicios de marketing; servicios de desarrollo creativo para campañas de marketing; servicios de agencia de publicidad; servicios de mercadeo digital.\", \"note\": \"Publicidad; gestión, organización y administración de negocios comerciales; trabajos de oficina.\"}]','[{\"code\": \"35\", \"text\": \"SERVICIO DE AGENCIA DE EMPLEO PARA NIÑERAS.\"}]',0,0,0,'1852946012195544','B68148','9488ca674f1cbf0e201487256468d2eb',105,'53befc4c55ade68d196c5ccf14fd134f',NULL,3,NULL,NULL,NULL,'Kanguritos','2025-12-30 15:03:41',NULL,'Kanguritos',NULL,'[9]','DANIEL  RESTREPO SOTO','Titerefue educación  S.A.S',NULL,'13241333',NULL,'2034-05-30',NULL,'',0,NULL,'2014-05-30','2013-10-31','',NULL,'2013-10-10'),(7,'http://sipi.sic.gov.co/sipi/View.ashx?622421',0,NULL,'[{\"code\": 45, \"more\": \"La clase 45 comprende principalmente los servicios jurídicos y de seguridad, así como ciertos servicios personales y sociales prestados por terceros para satisfacer necesidades individuales.\\nEsta clase comprende en particular:\\n\\n    •  los servicios de arbitraje y mediación\\n    •  el registro de nombres de dominio\\n    •  los servicios de auditoría de observancia jurídica y reglamentaria\\n    •  los servicios de investigación y vigilancia en relación con la seguridad física de personas y la seguridad de bienes\", \"note\": \"Servicios jurídicos; servicios de seguridad para la protección física de bienes materiales y personas; servicios de clubes de encuentro, servicios de redes sociales en línea; servicios funerarios; cuidado de niños a domicilio\\n\"}]','[{\"code\": \"45\", \"text\": \"SERVICIOS JURÍDICOS; SERVICIOS DE SEGURIDAD PARA LA PROTECCIÓN DE BIENES Y PERSONAS; SERVICIOS PERSONALES Y SOCIALES PRESTADOS POR TERCEROS PARA SATISFACER NECESIDADES INDIVIDUALES.\"}]',0,0,0,'1852946012213148','7DBE71','351ba8991252db522312b03b712d9511',105,'62a0280eeabdad713195dd5ec09c06c7',NULL,3,NULL,NULL,NULL,'estado','2025-12-30 15:03:41',NULL,'estado',NULL,'[10]','LAURA GIRALDO PALACIO','DANIEL  RESTREPO SOTO',NULL,'15232529',NULL,'2027-03-02',NULL,'',0,NULL,'2017-03-02',NULL,'',NULL,'2015-08-24'),(8,'http://sipi.sic.gov.co/sipi/View.ashx?625439',0,NULL,'[{\"code\": 31, \"more\": \"La clase 31 comprende principalmente los productos de la tierra y del mar que no hayan sido procesados para su consumo, los animales vivos y las plantas vivas, así como los alimentos para animales.\\nEsta clase comprende en particular:\\n\\n    •  los cereales sin procesar\\n    •  las frutas, verduras, hortalizas y legumbres frescas, incluso lavadas o enceradas\\n    •  los residuos de origen vegetal\\n    •  las algas sin procesar\\n    •  la madera sin desbastar\\n    •  los huevos fertilizados para incubar\\n    •  las t\", \"note\": \"Productos agrícolas, acuícolas, hortícolas y forestales en bruto y sin procesar; granos y semillas en bruto o sin procesar; frutas y verduras, hortalizas y legumbres frescas, hierbas aromáticas frescas; plantas y flores naturales; bulbos, plantones y semillas para plantar; animales vivos; productos alimenticios y bebidas para animales; malta\\n\"}]','[{\"code\": \"31\", \"text\": \"GRANOS Y PRODUCTOS AGRÍCOLAS, HORTÍCOLAS Y FORESTALES, NO COMPRENDIDOS EN OTRAS CLASES; ANIMALES VIVOS; FRUTAS Y VERDURAS, HORTALIZAS Y LEGUMBRES FRESCAS; SEMILLAS; PLANTAS Y FLORES NATURALES; ALIMENTOS PARA ANIMALES; MALTA.\"}]',0,0,0,'1852946012232998','EBB410','cac236dd1cb80a3858e581b38e307096',105,'9103063b02e468a4085bb61c2e30705f',NULL,3,NULL,NULL,NULL,'D&S Natural Life','2025-12-30 15:03:41',NULL,'D&S Natural Life',NULL,'[10]','DANIEL  RESTREPO SOTO','ANDREA BIBIANA GARCIA GARCIA',NULL,'15249301',NULL,'2026-10-19',NULL,'',0,NULL,'2016-10-19','2015-12-16','',NULL,'2015-10-20'),(9,'http://sipi.sic.gov.co/sipi/View.ashx?626349',0,NULL,'[{\"code\": 20, \"more\": \"La clase 20 comprende principalmente los muebles y sus partes, así como ciertos productos de madera, corcho, caña, junco, mimbre, cuerno, hueso, ballena, concha, ámbar, nácar, espuma de mar, sucedáneos de todos estos materiales o de materias plásticas.\\nEsta clase comprende en particular:\\n\\n    •  los muebles metálicos y los muebles de camping, los armeros para fusiles, los expositores para periódicos\\n    •  las persianas de interior para ventanas\\n    •  los accesorios de cama, por ejemplo: los colchones, los\", \"note\": \"Muebles, espejos, marcos; contenedores no metálicos de almacenamiento o transporte; hueso, cuerno, ballena o nácar, en bruto o semielaborados; conchas; espuma de mar; ámbar amarillo\\n\"}]','[{\"code\": \"20\", \"text\": \"Muebles, espejos, marcos.\"}]',0,0,0,'1852946012253461','9976DE','03a87e375d55bddfc66ca610213374ce',105,'07b3cfd68d583328884723751a166c7d',NULL,3,NULL,NULL,NULL,'Forja','2025-12-30 15:03:41',NULL,'Forja',NULL,'[10]','DANIEL  RESTREPO SOTO','ADMINISTRACIONES FC SAS',NULL,'15253824',NULL,'2031-03-18',NULL,'',0,NULL,'2021-03-18','2020-07-10','',NULL,'2015-10-23'),(10,'http://sipi.sic.gov.co/sipi/View.ashx?626766',0,NULL,'[{\"code\": 42, \"more\": \"Servicios de diseño; diseño de marca; diseño de contenido; diseño gráfico; diseño visual; diseño de branding, diseño publicitario; desarrollo de software; servicios de diseño y desarrollo web.\", \"note\": \"Servicios científicos y tecnológicos, así como servicios de investigación y diseño conexos; servicios de análisis industrial, investigación industrial y diseño industrial; control de calidad y servicios de autenticación; diseño y desarrollo de hardware y software.\"}]','[{\"code\": \"42\", \"text\": \"\\\"SERVICIOS CIENTÍFICOS Y TECNOLÓGICOS, DISEÑO Y DESARROLLO DE EQUIPOS INFORMÁTICOS, HARDWARE, SOFTWARE Y APLICACIONES WEB”\"}]',0,0,0,'1852946012271123','9976DE','2f25fc9d2ff8c49e34fdf03f02c02080',105,'bd66ef64d616dfe0f8e9d74fbdad0708',NULL,1,NULL,NULL,NULL,'Nebular','2025-12-30 15:03:41',NULL,'Nebular',NULL,'[10]','LAURA GIRALDO PALACIO','NEBULAR S.A.S.',NULL,'15256937',NULL,NULL,NULL,'',0,NULL,NULL,'2015-11-20','',NULL,'2015-10-28'),(11,'http://sipi.sic.gov.co/sipi/View.ashx?635449',0,NULL,'[{\"code\": 29, \"more\": \"La clase 29 comprende principalmente los productos alimenticios de origen animal, las verduras, hortalizas y legumbres, así como otros productos hortícolas comestibles preparados o en conserva para su consumo.\\nEsta clase comprende en particular:\\n\\n    •  los alimentos a base de carne, pescado, fruta o verduras, hortalizas y legumbres\\n    •  los insectos comestibles\\n    •  las bebidas lacteadas en las que predomine la leche\\n    •  los sucedáneos de la leche, por ejemplo: la leche de almendras, la leche de coc\", \"note\": \"Carne, pescado, carne de ave y carne de caza; extractos de carne; frutas y verduras, hortalizas y legumbres en conserva, congeladas, secas y cocidas; jaleas, mermeladas, compotas; huevos; leche, quesos, mantequilla, yogur y otros productos lácteos; aceites y grasas para uso alimenticio\\n\"}]','[{\"code\": \"29\", \"text\": \"LECHE, PRODUCTOS LÁCTEOS Y DERIVADOS.\"}]',0,0,0,'1852946012289582','7DBE71','00a474a589f77428b9acec706e4e4a11',105,'2bdf6d102292b0ed1ef919e01bcc88d2',NULL,3,NULL,NULL,NULL,'VALENTI','2025-12-30 15:03:41',NULL,'VALENTI',NULL,'[10]','DANIEL  RESTREPO SOTO','COMPAÑIA LATINA DE ALIMENTOS S.A.S.',NULL,'15303435',NULL,'2027-07-24',NULL,'',0,NULL,'2017-07-24','2016-01-15','',NULL,'2015-12-22'),(12,'http://sipi.sic.gov.co/sipi/View.ashx?635451',0,NULL,'[{\"code\": 30, \"more\": \"La clase 30 comprende principalmente los productos alimenticios de origen vegetal, excepto las frutas, verduras, hortalizas y legumbres preparados o en conserva para su consumo, así como los aditivos para realzar el sabor de los alimentos.\\nEsta clase comprende en particular:\\n\\n    •  las bebidas a base de café, cacao, chocolate o té\\n    •  los cereales preparados para la alimentación humana, por ejemplo: los copos de avena, los chips de maíz, la cebada mondada, el bulgur, el muesli\\n    •  las pizzas, las tar\", \"note\": \"Café, té, cacao y sus sucedáneos; arroz, pastas alimenticias y fideos; tapioca y sagú; harinas y prepa