DROP TABLE IF EXISTS `pasts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pasts` (
  `row` int NOT NULL AUTO_INCREMENT,
  `test` tinyint(1) DEFAULT '0',
  `lock` tinyint(1) DEFAULT '0',
  `hide` tinyint(1) DEFAULT '0',
  `skip` int NOT NULL,
  `code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `hash` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `bind` int NOT NULL,
  `date` datetime NOT NULL,
  `data` json NOT NULL,
  `card` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `cost` float NOT NULL,
  `type` tinyint(1) NOT NULL,
  `wipe` datetime DEFAULT NULL,
  `mark` datetime DEFAULT NULL,
  PRIMARY KEY (`row`),
  UNIQUE KEY `hash_UNIQUE` (`hash`)
) ENGINE=InnoDB AUTO_INCREMENT=79 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

