DROP TABLE IF EXISTS `tasks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tasks` (
  `row` int NOT NULL AUTO_INCREMENT,
  `lock` tinyint DEFAULT '0',
  `hide` tinyint(1) DEFAULT '0',
  `seek` int DEFAULT NULL,
  `hash` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `date` date DEFAULT NULL,
  `time` int DEFAULT NULL,
  `skip` int NOT NULL,
  `link` int DEFAULT NULL,
  `bind` int NOT NULL,
  `rank` tinyint(1) DEFAULT '0',
  `note` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `done` tinyint(1) DEFAULT '0',
  `head` int DEFAULT NULL,
  `wipe` datetime DEFAULT NULL,
  `mark` datetime DEFAULT NULL,
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `made` datetime NOT NULL,
  PRIMARY KEY (`row`),
  UNIQUE KEY `hash_UNIQUE` (`hash`)
) ENGINE=InnoDB AUTO_INCREMENT=2960 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
